/**
 * Normalizes text for robust Arabic and English fuzzy searching
 */
export function normalizeSearchString(text: string): string {
  if (!text) return '';
  return text
    .toLowerCase()
    .replace(/[أإآ]/g, 'ا')
    .replace(/[ة]/g, 'ه')
    .replace(/[ى]/g, 'ي')
    .replace(/[ؤئ]/g, 'ء')
    .replace(/[ً-ٟ]/g, '') // strip Arabic diacritics
    .replace(/[^a-z0-9؀-ۿ\s]/g, '')
    .trim();
}

/**
 * Searches the preset perfume database by keyword (Arabic or English) and optional brand filter
 */
export function searchPerfumeDatabase(query: string, brandFilter?: string, limit = 12): PerfumePresetSpec[] {
  let list = PERFUME_PRESETS_DATABASE;

  if (brandFilter && brandFilter !== 'الكل') {
    const cleanBrand = normalizeSearchString(brandFilter);
    list = list.filter((p) => normalizeSearchString(p.brand).includes(cleanBrand));
  }

  if (!query || query.trim().length === 0) {
    return list.slice(0, limit);
  }

  const cleanQuery = normalizeSearchString(query);
  const words = cleanQuery.split(/\s+/).filter(Boolean);

  const matched = list.filter((perfume) => {
    const haystack = [
      normalizeSearchString(perfume.nameAr),
      normalizeSearchString(perfume.nameEn),
      normalizeSearchString(perfume.brand),
      ...perfume.searchKeywords.map(normalizeSearchString)
    ].join(' ');

    // Match if all query words appear in haystack
    return words.every((word) => haystack.includes(word));
  });

  return matched.slice(0, limit);
}

/**
 * Finds the single best matching perfume preset for a given input name
 */
export function findBestMatchingPerfume(name: string): PerfumePresetSpec | undefined {
  if (!name || name.trim().length < 2) return undefined;
  const results = searchPerfumeDatabase(name, undefined, 1);
  return results[0];
}
